using System.Data;using System.Security.Claims;using Laoo.Shared.Contracts;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;
namespace LaooTimeModule.Controllers;
[ApiController,Authorize,Route("api/time/employee-schedules")]
public sealed class EmployeeSchedulesController(IConfiguration configuration):ControllerBase{
 const string MenuCode="27004";
 public sealed record AssignmentRequest(long EmployeeId,long WorkScheduleGroupId,DateOnly EffectiveFrom,DateOnly? EffectiveTo,string Reason);
 public sealed record RotationRequest(long WorkScheduleGroupId,long RotationPatternId,DateOnly AnchorDate,DateOnly EffectiveFrom,DateOnly? EffectiveTo,string Reason);
 public sealed record OverrideRequest(long EmployeeId,DateOnly WorkDate,bool IsDayOff,long? ShiftTemplateId,long? WorkBranchId,string Reason,string? RowVersion);
 [HttpGet("actions")]public async Task<IActionResult>Actions(CancellationToken t){if(!Scope(out _,out _))return Forbid();await using var c=await Open(t);return Ok(new{menuCode=MenuCode,caption=await Caption(c,t),screenType=1,view=await Can(c,"VIEW",t),create=await Can(c,"CREATE",t),edit=await Can(c,"EDIT",t),delete=await Can(c,"DELETE",t)});}
 [HttpGet("lookups")]public async Task<IActionResult>Lookups(CancellationToken t){if(!Scope(out var co,out _))return Forbid();await using var c=await Open(t);if(!await Can(c,"VIEW",t))return Forbid();return Ok(new{employees=await Lookup(c,"SELECT EmployeeID Id,EmployeeCode Code,FullName Name FROM dbo.TDADEmployee WHERE CompanyID=@C AND IsActive=1 ORDER BY EmployeeCode",co,t),groups=await Lookup(c,"SELECT WorkScheduleGroupID Id,GroupCode Code,GroupName Name FROM dbo.TDTMWorkScheduleGroup WHERE CompanyID=@C AND IsActive=1 ORDER BY GroupCode",co,t),patterns=await Lookup(c,"SELECT RotationPatternID Id,PatternCode Code,PatternName Name FROM dbo.TDTMRotationPattern WHERE CompanyID=@C AND IsActive=1 ORDER BY PatternCode",co,t),shifts=await Lookup(c,"SELECT ShiftTemplateID Id,ShiftCode Code,ShiftName Name FROM dbo.TDTMShiftTemplate WHERE CompanyID=@C AND IsActive=1 ORDER BY ShiftCode",co,t)});}
 [HttpGet]public async Task<IActionResult>List([FromQuery]string?search,[FromQuery]int page=1,[FromQuery]int pageSize=30,CancellationToken t=default){if(!Scope(out var co,out _))return Forbid();if(page<1||pageSize is<1 or>100)return BadRequest(new{message="หน้าหรือจำนวนรายการต่อหน้าไม่ถูกต้อง"});await using var c=await Open(t);if(!await Can(c,"VIEW",t))return Forbid();search=Clean(search);const string w="FROM dbo.TDADEmployee E OUTER APPLY(SELECT TOP(1)A.WorkScheduleGroupAssignmentID,A.WorkScheduleGroupID,A.EffectiveFrom,A.EffectiveTo,CONVERT(varchar(32),A.RowVersion,2)RowVersion FROM dbo.TDTMWorkScheduleGroupAssignment A WHERE A.CompanyID=E.CompanyID AND A.EmployeeID=E.EmployeeID AND A.IsActive=1 AND A.EffectiveFrom<=CONVERT(date,GETDATE()) AND(A.EffectiveTo IS NULL OR A.EffectiveTo>=CONVERT(date,GETDATE()))ORDER BY A.EffectiveFrom DESC)A LEFT JOIN dbo.TDTMWorkScheduleGroup G ON G.CompanyID=E.CompanyID AND G.WorkScheduleGroupID=A.WorkScheduleGroupID WHERE E.CompanyID=@C AND E.IsActive=1 AND(@S IS NULL OR E.EmployeeCode LIKE N'%'+@S+N'%' OR E.FullName LIKE N'%'+@S+N'%' OR G.GroupName LIKE N'%'+@S+N'%')";await using var count=new SqlCommand($"SELECT COUNT_BIG(1){w}",c);Bind(count,co,search);var total=Convert.ToInt64(await count.ExecuteScalarAsync(t));await using var q=new SqlCommand($"SELECT E.EmployeeID,E.EmployeeCode,E.FullName,A.WorkScheduleGroupAssignmentID,A.WorkScheduleGroupID,G.GroupCode,G.GroupName,A.EffectiveFrom,A.EffectiveTo,A.RowVersion {w} ORDER BY E.EmployeeCode OFFSET @O ROWS FETCH NEXT @N ROWS ONLY",c);Bind(q,co,search);Add(q,"@O",SqlDbType.Int,(page-1)*pageSize);Add(q,"@N",SqlDbType.Int,pageSize);await using var r=await q.ExecuteReaderAsync(t);var items=new List<object>();while(await r.ReadAsync(t))items.Add(new{employeeId=r.GetInt64(0),employeeCode=r.GetString(1),fullName=r.GetString(2),assignmentId=r.IsDBNull(3)?null:(long?)r.GetInt64(3),workScheduleGroupId=r.IsDBNull(4)?null:(long?)r.GetInt64(4),groupCode=r.IsDBNull(5)?null:r.GetString(5),groupName=r.IsDBNull(6)?null:r.GetString(6),effectiveFrom=r.IsDBNull(7)?null:(DateOnly?)DateOnly.FromDateTime(r.GetDateTime(7)),effectiveTo=r.IsDBNull(8)?null:(DateOnly?)DateOnly.FromDateTime(r.GetDateTime(8)),rowVersion=r.IsDBNull(9)?null:r.GetString(9)});return Ok(new{total,page,pageSize,items});}
 [HttpPost("assignments")]public async Task<IActionResult>Assign(AssignmentRequest x,CancellationToken t){if(!Scope(out var co,out var user))return Forbid();if(x.EffectiveFrom<DateOnly.FromDateTime(DateTime.Today)||x.EffectiveTo<x.EffectiveFrom||Clean(x.Reason)is null)return BadRequest(new{message="วันที่หรือเหตุผลไม่ถูกต้อง"});await using var c=await Open(t);if(!await Can(c,"EDIT",t))return Forbid();await using var tx=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable,t);try{if(!await Exists(c,tx,"TDADEmployee","EmployeeID",co,x.EmployeeId,t)||!await Exists(c,tx,"TDTMWorkScheduleGroup","WorkScheduleGroupID",co,x.WorkScheduleGroupId,t))throw new InvalidOperationException("พนักงานหรือกลุ่มไม่อยู่ในบริษัท");await CloseOpen(c,tx,"TDTMWorkScheduleGroupAssignment","WorkScheduleGroupAssignmentID","EmployeeID",co,x.EmployeeId,x.EffectiveFrom,user,t);await using var q=new SqlCommand("INSERT dbo.TDTMWorkScheduleGroupAssignment(CompanyID,EmployeeID,WorkScheduleGroupID,EffectiveFrom,EffectiveTo,Reason,IsActive,CreateBy)VALUES(@C,@E,@G,@F,@T,@R,1,@U)",c,tx);Add(q,"@C",SqlDbType.BigInt,co);Add(q,"@E",SqlDbType.BigInt,x.EmployeeId);Add(q,"@G",SqlDbType.BigInt,x.WorkScheduleGroupId);Add(q,"@F",SqlDbType.Date,x.EffectiveFrom.ToDateTime(TimeOnly.MinValue));Add(q,"@T",SqlDbType.Date,x.EffectiveTo?.ToDateTime(TimeOnly.MinValue));Add(q,"@R",SqlDbType.NVarChar,x.Reason.Trim(),1000);Add(q,"@U",SqlDbType.BigInt,user);await q.ExecuteNonQueryAsync(t);await tx.CommitAsync(t);return NoContent();}catch(InvalidOperationException e){await tx.RollbackAsync(t);return Conflict(new{message=e.Message});}}
 [HttpPost("group-rotations")]public async Task<IActionResult>Rotate(RotationRequest x,CancellationToken t){if(!Scope(out var co,out var user))return Forbid();if(x.EffectiveFrom<DateOnly.FromDateTime(DateTime.Today)||x.EffectiveTo<x.EffectiveFrom||Clean(x.Reason)is null)return BadRequest(new{message="วันที่หรือเหตุผลไม่ถูกต้อง"});await using var c=await Open(t);if(!await Can(c,"EDIT",t))return Forbid();await using var tx=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable,t);try{if(!await Exists(c,tx,"TDTMWorkScheduleGroup","WorkScheduleGroupID",co,x.WorkScheduleGroupId,t)||!await Exists(c,tx,"TDTMRotationPattern","RotationPatternID",co,x.RotationPatternId,t))throw new InvalidOperationException("กลุ่มหรือรูปแบบหมุนกะไม่อยู่ในบริษัท");await CloseOpen(c,tx,"TDTMGroupShiftRotation","GroupShiftRotationID","WorkScheduleGroupID",co,x.WorkScheduleGroupId,x.EffectiveFrom,user,t);await using var q=new SqlCommand("INSERT dbo.TDTMGroupShiftRotation(CompanyID,WorkScheduleGroupID,RotationPatternID,AnchorDate,EffectiveFrom,EffectiveTo,IsActive,Reason,CreateBy)VALUES(@C,@G,@P,@A,@F,@T,1,@R,@U)",c,tx);Add(q,"@C",SqlDbType.BigInt,co);Add(q,"@G",SqlDbType.BigInt,x.WorkScheduleGroupId);Add(q,"@P",SqlDbType.BigInt,x.RotationPatternId);Add(q,"@A",SqlDbType.Date,x.AnchorDate.ToDateTime(TimeOnly.MinValue));Add(q,"@F",SqlDbType.Date,x.EffectiveFrom.ToDateTime(TimeOnly.MinValue));Add(q,"@T",SqlDbType.Date,x.EffectiveTo?.ToDateTime(TimeOnly.MinValue));Add(q,"@R",SqlDbType.NVarChar,x.Reason.Trim(),1000);Add(q,"@U",SqlDbType.BigInt,user);await q.ExecuteNonQueryAsync(t);await tx.CommitAsync(t);return NoContent();}catch(InvalidOperationException e){await tx.RollbackAsync(t);return Conflict(new{message=e.Message});}}
 [HttpPost("overrides")]public async Task<IActionResult>Override(OverrideRequest x,CancellationToken t){if(!Scope(out var co,out var user))return Forbid();if(x.WorkDate<DateOnly.FromDateTime(DateTime.Today)||Clean(x.Reason)is null||(x.IsDayOff&&x.ShiftTemplateId!=null)||(!x.IsDayOff&&x.ShiftTemplateId==null))return BadRequest(new{message="ข้อมูลตารางเฉพาะวันไม่ถูกต้อง"});await using var c=await Open(t);if(!await Can(c,"EDIT",t))return Forbid();if(!await Exists(c,null,"TDADEmployee","EmployeeID",co,x.EmployeeId,t)||x.ShiftTemplateId!=null&&!await Exists(c,null,"TDTMShiftTemplate","ShiftTemplateID",co,x.ShiftTemplateId.Value,t))return Conflict(new{message="พนักงานหรือกะไม่อยู่ในบริษัท"});await using var q=new SqlCommand("UPDATE dbo.TDTMScheduleOverride SET IsDayOff=@Off,ShiftTemplateID=@Shift,WorkBranchID=@Branch,Reason=@R,IsActive=1,UpdateDate=SYSDATETIME(),UpdateBy=@U WHERE CompanyID=@C AND EmployeeID=@E AND WorkDate=@D;IF @@ROWCOUNT=0 INSERT dbo.TDTMScheduleOverride(CompanyID,EmployeeID,WorkDate,IsDayOff,ShiftTemplateID,WorkBranchID,Reason,IsActive,CreateBy)VALUES(@C,@E,@D,@Off,@Shift,@Branch,@R,1,@U)",c);Add(q,"@C",SqlDbType.BigInt,co);Add(q,"@E",SqlDbType.BigInt,x.EmployeeId);Add(q,"@D",SqlDbType.Date,x.WorkDate.ToDateTime(TimeOnly.MinValue));Add(q,"@Off",SqlDbType.Bit,x.IsDayOff);Add(q,"@Shift",SqlDbType.BigInt,x.ShiftTemplateId);Add(q,"@Branch",SqlDbType.BigInt,x.WorkBranchId);Add(q,"@R",SqlDbType.NVarChar,x.Reason.Trim(),1000);Add(q,"@U",SqlDbType.BigInt,user);await q.ExecuteNonQueryAsync(t);return NoContent();}
 static async Task CloseOpen(SqlConnection c,SqlTransaction tx,string table,string idCol,string ownerCol,long co,long owner,DateOnly start,long user,CancellationToken t){await using var q=new SqlCommand($"SELECT TOP(1){idCol},EffectiveFrom FROM dbo.{table} WITH(UPDLOCK,HOLDLOCK) WHERE CompanyID=@C AND {ownerCol}=@Owner AND IsActive=1 AND EffectiveTo IS NULL ORDER BY EffectiveFrom DESC",c,tx);Add(q,"@C",SqlDbType.BigInt,co);Add(q,"@Owner",SqlDbType.BigInt,owner);await using var r=await q.ExecuteReaderAsync(t);if(!await r.ReadAsync(t))return;var id=r.GetInt64(0);var old=DateOnly.FromDateTime(r.GetDateTime(1));await r.CloseAsync();if(old>=start)throw new InvalidOperationException("วันที่เริ่มใช้ต้องหลังรายการปัจจุบัน");await using var u=new SqlCommand($"UPDATE dbo.{table} SET EffectiveTo=DATEADD(day,-1,@F) WHERE CompanyID=@C AND {idCol}=@ID",c,tx);Add(u,"@F",SqlDbType.Date,start.ToDateTime(TimeOnly.MinValue));Add(u,"@C",SqlDbType.BigInt,co);Add(u,"@ID",SqlDbType.BigInt,id);await u.ExecuteNonQueryAsync(t);}
 static async Task<bool>Exists(SqlConnection c,SqlTransaction?tx,string table,string col,long co,long id,CancellationToken t){await using var q=new SqlCommand($"SELECT COUNT(1)FROM dbo.{table} WHERE CompanyID=@C AND {col}=@ID AND IsActive=1",c,tx);Add(q,"@C",SqlDbType.BigInt,co);Add(q,"@ID",SqlDbType.BigInt,id);return Convert.ToInt32(await q.ExecuteScalarAsync(t))==1;}static async Task<List<object>>Lookup(SqlConnection c,string sql,long co,CancellationToken t){await using var q=new SqlCommand(sql,c);Add(q,"@C",SqlDbType.BigInt,co);await using var r=await q.ExecuteReaderAsync(t);var x=new List<object>();while(await r.ReadAsync(t))x.Add(new{id=r.GetInt64(0),code=r.GetString(1),name=r.GetString(2)});return x;}
 private async Task<bool>Can(SqlConnection c,string a,CancellationToken t)=>await CompanyMenuAccess.IsAllowedAsync(c,User,MenuCode,a,t);private async Task<SqlConnection>Open(CancellationToken t){var c=new SqlConnection(configuration.GetConnectionString("LaooDatabase"));await c.OpenAsync(t);return c;}private bool Scope(out long c,out long u){c=0;u=0;return string.Equals(User.FindFirstValue("user_type"),"COMPANY_USER",StringComparison.OrdinalIgnoreCase)&&long.TryParse(User.FindFirstValue("company_id"),out c)&&long.TryParse(User.FindFirstValue("user_id"),out u)&&c>0&&u>0;}private static async Task<string>Caption(SqlConnection c,CancellationToken t){await using var q=new SqlCommand("SELECT TOP(1)MenuName FROM dbo.TDADMainMenu WHERE MenuCode=@M",c);Add(q,"@M",SqlDbType.Char,MenuCode,5);return Convert.ToString(await q.ExecuteScalarAsync(t))??"จัดตารางพนักงาน";}static void Bind(SqlCommand q,long c,string?s){Add(q,"@C",SqlDbType.BigInt,c);Add(q,"@S",SqlDbType.NVarChar,s,150);}static string?Clean(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();static void Add(SqlCommand q,string n,SqlDbType t,object?v,int s=0){var p=s==0?q.Parameters.Add(n,t):q.Parameters.Add(n,t,s);p.Value=v??DBNull.Value;}
}
